 static class NativeWorld extends World {
  final Map<Long,Chunk> chunks=new HashMap<>();final java.util.List<net.minecraft.entity.item.EntityItem> drops=new java.util.ArrayList<>();
  @Override public boolean spawnEntity(net.minecraft.entity.Entity e){drops.add((net.minecraft.entity.item.EntityItem)e);return true;}
  NativeWorld(boolean client){super(new SaveHandlerMP(),new WorldInfo(new NBTTagCompound()),new WorldProviderSurface(),new Profiler(),client);provider.setWorld(this);chunkProvider=createChunkProvider();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){Chunk c=new Chunk(this,x,z);c.markLoaded(true);chunks.put(key(x,z),c);}TileAccessCache.cache.clear();}
  static long key(int x,int z){return ((long)x<<32)^(z&0xffffffffL);}
  @Override protected IChunkProvider createChunkProvider(){return new IChunkProvider(){public Chunk getLoadedChunk(int x,int z){return chunks.get(key(x,z));}public Chunk provideChunk(int x,int z){return getLoadedChunk(x,z);}public boolean tick(){return false;}public String makeString(){return "RTG native chunks";}public boolean isChunkGeneratedAt(int x,int z){return chunks.containsKey(key(x,z));}};}
  @Override protected boolean isChunkLoaded(int x,int z,boolean allowEmpty){return chunks.containsKey(key(x,z));}
  @Override public boolean checkLight(BlockPos p){return true;}
  <T extends TileEntity>T put(BlockPos pos,Block h){setBlockState(pos,h.getDefaultState(),3);return (T)getTileEntity(pos);}
 }
