 static void setup(){rtg=new com.hbm.blocks.machine.MachineRTG(Material.ROCK);rtg.setRegistryName("hbm","probe_rtg");ForgeRegistries.BLOCKS.register(rtg);com.hbm.blocks.ModBlocks.machine_rtg_grey=rtg;TileEntity.register("hbm:probe_rtg",TileEntityMachineRTG.class);mini=new com.hbm.blocks.machine.MachineMiniRTG(Material.ROCK);mini.setRegistryName("hbm","probe_mini");ForgeRegistries.BLOCKS.register(mini);com.hbm.blocks.ModBlocks.machine_minirtg=mini;TileEntity.register("hbm:probe_mini",TileEntityMachineMiniRTG.class);sink=host("probe_sink",Sink::new,Sink.class);pellet=new ItemRTGPellet(40);pellet.setRegistryName("hbm","probe_pellet");ForgeRegistries.ITEMS.register(pellet);com.hbm.items.ModItems.pellet_rtg=pellet;com.hbm.items.ModItems.pellet_rtg_depleted=Items.IRON_INGOT;}
 static void inventory() throws Exception {
  TileEntityMachineRTG a=new NativeWorld(false).put(P,rtg);check(a.isEmpty()&&a.getSizeInventory()==15,"15 empty slots");for(int i=0;i<15;i++){check(a.getStackInSlot(i)==ItemStack.EMPTY,"native empty get");check(a.decrStackSize(i,1)==ItemStack.EMPTY,"native empty decrement");check(a.removeStackFromSlot(i)==ItemStack.EMPTY,"native empty remove");}
  a.setInventorySlotContents(0,new ItemStack(pellet,80));check(a.getStackInSlot(0).getCount()==64,"original inventory cap remains 64 even for pellets");check(a.decrStackSize(0,3).getCount()==3&&a.getStackInSlot(0).getCount()==61,"split accounting");check(a.decrStackSize(0,99).getCount()==61&&a.isEmpty(),"full decrement accounting");a.setInventorySlotContents(0,ItemStack.EMPTY);a.setInventorySlotContents(1,null);check(a.isEmpty(),"both absence inputs accepted");
  for(EnumFacing f:EnumFacing.values()){check(a.getSlotsForFace(f).length==15,"all faces 15 slots");check(a.canInsertItem(0,new ItemStack(pellet),f)&&!a.canInsertItem(0,new ItemStack(Items.APPLE),f)&&!a.canExtractItem(0,new ItemStack(pellet),f),"pellet-only insertion no extraction");}
  a.setCustomName("RTG test");a.power=12345;a.heat=137;a.muffled=true;ItemStack tagged=new ItemStack(pellet);tagged.setTagCompound(new NBTTagCompound());tagged.getTagCompound().setLong("PELLET_DEPLETION",987);a.setInventorySlotContents(14,tagged);NBTTagCompound n=a.writeToNBT(new NBTTagCompound());java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();CompressedStreamTools.writeCompressed(n,out);n=CompressedStreamTools.readCompressed(new java.io.ByteArrayInputStream(out.toByteArray()));TileEntityMachineRTG b=new TileEntityMachineRTG();b.readFromNBT(n);check(b.power==12345&&b.heat==137&&b.muffled&&b.hasCustomName()&&b.getName().equals("RTG test"),"real compressed NBT state/name/base roundtrip");check(b.getStackInSlot(14).getTagCompound().getLong("PELLET_DEPLETION")==987&&b.getStackInSlot(0)==ItemStack.EMPTY,"inventory tag/native absence roundtrip");
  NBTTagList list=n.getTagList("items",10);NBTTagCompound invalid=new NBTTagCompound();invalid.setString("id","missing:no_item");invalid.setByte("Count",(byte)1);invalid.setByte("slot",(byte)14);list.appendTag(invalid);b.readFromNBT(n);check(b.isEmpty(),"invalid item normalizes native EMPTY to absent domain storage");b.setInventorySlotContents(0,new ItemStack(pellet));b.clear();check(b.isEmpty()&&b.getFieldCount()==0,"clear and native no window fields");
  ByteBuf buf=Unpooled.buffer();a.serialize(buf);check(buf.readableBytes()==9,"original byte payload bool plus long, no invented heat sync");b.heat=19;b.deserialize(buf);check(b.power==12345&&b.muffled&&b.heat==19,"native network serialization preserves original payload");buf.release();
 }
 static void energy(){
  for(long initial:new long[]{0,1,999,100000})for(long stored:new long[]{0,999,1000})for(long speed:new long[]{0,1,777,1000}){
   NativeWorld w=new NativeWorld(false);TileEntityMachineRTG a=w.put(P,rtg);Sink b=w.put(P.down(),sink);a.power=initial;b.power=stored;b.max=1000;b.speed=speed;long expected=Math.min(initial,Math.min(1000-stored,speed));a.tryProvide(w,4,19,4,ForgeDirection.DOWN);check(a.power==initial-expected&&b.power==stored+expected,"actual provider debit equals receipt at zero/caps/speed");
  }
  NativeWorld w=new NativeWorld(false);TileEntityMachineRTG a=w.put(P,rtg);Sink b=w.put(P.down(),sink);a.setInventorySlotContents(0,new ItemStack(pellet));a.power=0;a.update();check(b.power==0&&a.power==200&&a.heat==40,"RTG provides BEFORE generation");a.update();check(b.power==200&&a.power==200,"next tick provides prior energy");a.clear();a.power=99999;b.allowed=false;a.update();check(a.power==99999&&a.heat==0,"direct provision blocked preserves energy without fuel");a.setInventorySlotContents(0,new ItemStack(pellet));a.update();check(a.power==100000,"generation clamps overflow to original powerMax");for(int i=1;i<15;i++)a.setInventorySlotContents(i,new ItemStack(pellet));a.power=0;a.update();check(a.heat==200&&a.power==1000&&a.getHeatScaled(100)==100,"nondecay heat cap 200 and factor five");
  b.allowed=true;b.connected=false;a.power=321;a.tryProvide(w,4,19,4,ForgeDirection.DOWN);check(a.power==321,"opposite disconnected face rejects");
  NativeWorld cw=new NativeWorld(true);TileEntityMachineRTG client=cw.put(P,rtg);client.setInventorySlotContents(0,new ItemStack(pellet));client.power=71;client.heat=23;int calls=PacketThreading.calls;client.update();check(client.power==71&&client.heat==23&&PacketThreading.calls==calls,"client never generates/provides/sends");
  NativeWorld mw=new NativeWorld(false);TileEntityMachineMiniRTG m=mw.put(P,mini);Sink ms=mw.put(P.down(),sink);m.update();check(ms.power==700&&m.power==0,"mini generates BEFORE provision");ms.allowed=false;m.update();m.update();m.update();check(m.power==1400,"mini 1400 cap");com.hbm.blocks.ModBlocks.machine_powerrtg=mini;check(m.getOutput()==2500&&m.getMaxPower()==50000,"unchanged preexisting power-RTG branch values");com.hbm.blocks.ModBlocks.machine_powerrtg=null;
 }
 static void lifecycleAndBoundaries() throws Exception {
  NativeWorld w=new NativeWorld(false);TileEntityMachineRTG a=w.put(P,rtg);check(w.tickableTileEntities.contains(a)&&w.loadedTileEntityList.contains(a),"native chunk registers RTG tick owner");a.setInventorySlotContents(0,new ItemStack(pellet));int calls=PacketThreading.calls;w.updateEntities();check(a.power==200&&PacketThreading.calls==calls+1,"native World.updateEntities dispatches actual tile and packet");check(PacketThreading.target.range==50&&PacketThreading.target.x==4&&PacketThreading.target.y==20&&PacketThreading.target.z==4,"original packet radius and native coordinates");ByteBuf packet=PacketThreading.packet.getCompiledBuffer().duplicate();check(packet.readInt()==4&&packet.readInt()==20&&packet.readInt()==4&&!packet.readBoolean()&&packet.readLong()==200&&!packet.isReadable(),"actual BufPacket serializer body has coordinate prefix and exact original tile payload");
  check(!a.shouldRefresh(w,P,Blocks.FURNACE.getStateFromMeta(2),Blocks.FURNACE.getStateFromMeta(3))&&a.shouldRefresh(w,P,rtg.getDefaultState(),mini.getDefaultState()),"native default keeps metadata-only tile changes and replaces block changes");
  a.clear();a.power=350;Sink[] receivers=new Sink[6];for(ForgeDirection d:ForgeDirection.VALID_DIRECTIONS){Sink b=w.put(P.add(d.offsetX,d.offsetY,d.offsetZ),sink);b.max=100;receivers[d.ordinal()]=b;}TileAccessCache.cache.clear();a.update();check(a.power==0,"all six sides debit only total initial power");long[] expected={100,100,100,50,0,0};for(int i=0;i<6;i++)check(receivers[i].power==expected[i],"original direction iteration determines priority "+i);
  Sink partial=new Sink(){@Override public long transferPower(long offered){long accept=offered/2;power+=accept;return offered-accept;}};w.setTileEntity(P.down(),partial);TileAccessCache.cache.clear();a.power=80;a.tryProvide(w,4,19,4,ForgeDirection.DOWN);check(a.power==40&&partial.power==40,"source debits accepted receipt after receiver remainder");
  TileEntityMachineRTG throttled=new TileEntityMachineRTG(){@Override public long getProviderSpeed(){return 7;}};throttled.power=50;partial.power=0;throttled.tryProvide(w,4,19,4,ForgeDirection.DOWN);check(throttled.power==47&&partial.power==3,"provider speed cap precedes receiver rejection");
  Sink direct=new Sink();direct.max=100;direct.power=95;check(direct.transferPower(12)==7&&direct.power==100,"actual receiver default returns overflow not source loss");
  a.onChunkUnload();check(!a.isLoaded(),"original loaded-base unload contract");
 }
