 static void blockCallbacks()throws Exception {
  NativeWorld w=new NativeWorld(false);TileEntityMachineRTG a=w.put(P,rtg);a.power=77;a.heat=13;a.setCustomName("retained");ItemStack fuel=new ItemStack(pellet,64,2);NBTTagCompound tag=new NBTTagCompound();tag.setString("proof","copied");fuel.setTagCompound(tag);a.setInventorySlotContents(0,fuel);
  for(int i=0;i<16;i++){w.setBlockState(P,rtg.getStateFromMeta(i),2);check(w.getTileEntity(P)==a&&a.power==77&&a.heat==13&&a.getStackInSlot(0)==fuel&&!a.isInvalid(),"all native RTG metadata states retain exact owner and inventory "+i);}
  TileEntityMachineMiniRTG m=w.put(P.east(3),mini);m.power=99;for(int i=0;i<16;i++){w.setBlockState(P.east(3),mini.getStateFromMeta(i),2);check(w.getTileEntity(P.east(3))==m&&m.power==99,"all native Mini metadata states retain owner "+i);}
  Player p=new Player(w);p.setPosition(4.5,20.5,4.5);check(a.isUsableByPlayer(p),"native usability identifies this tile");p.setPosition(13,20.5,4.5);check(!a.isUsableByPlayer(p),"original eight-block usability limit");
  for(EnumFacing side:EnumFacing.values())check(!rtg.isSideSolid(rtg.getDefaultState(),w,P,side)&&rtg.getBlockFaceShape(w,rtg.getDefaultState(),P,side)==net.minecraft.block.state.BlockFaceShape.UNDEFINED,"RTG remains non-solid on all faces");check(!rtg.isOpaqueCube(rtg.getDefaultState())&&!rtg.isFullCube(rtg.getDefaultState())&&rtg.getRenderType(rtg.getDefaultState())==EnumBlockRenderType.ENTITYBLOCK_ANIMATED,"actual RTG TESR route and geometry flags");
  com.hbm.blocks.machine.MachineRTG shell=new com.hbm.blocks.machine.MachineRTG(Material.ROCK);check(shell.createNewTileEntity(w,0)==null,"non-grey RTG original no tile");check(!mini.onBlockActivated(w,P.east(3),mini.getDefaultState(),p,EnumHand.MAIN_HAND,EnumFacing.UP,0,0,0),"Mini preserves no GUI activation");p.setSneaking(true);check(!rtg.onBlockActivated(w,P,rtg.getDefaultState(),p,EnumHand.MAIN_HAND,EnumFacing.UP,0,0,0),"sneaking grey does not open");check(rtg.onBlockActivated(new NativeWorld(true),P,rtg.getDefaultState(),p,EnumHand.MAIN_HAND,EnumFacing.UP,0,0,0),"client consumes activation even sneaking");
  final int[] gui={0};net.minecraftforge.fml.common.network.NetworkRegistry.INSTANCE.registerGuiHandler(com.hbm.main.MainRegistry.instance,new net.minecraftforge.fml.common.network.IGuiHandler(){public Object getServerGuiElement(int id,net.minecraft.entity.player.EntityPlayer player,World world,int x,int y,int z){check(id==0&&world==w&&x==4&&y==20&&z==4,"actual Forge GUI dispatch exact original ID/world/position");gui[0]++;return null;}public Object getClientGuiElement(int id,net.minecraft.entity.player.EntityPlayer player,World world,int x,int y,int z){throw new AssertionError("client GUI");}});
  java.lang.reflect.Field uf=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");uf.setAccessible(true);GuiPlayer gp=(GuiPlayer)((sun.misc.Unsafe)uf.get(null)).allocateInstance(GuiPlayer.class);check(rtg.onBlockActivated(w,P,rtg.getDefaultState(),gp,EnumHand.MAIN_HAND,EnumFacing.UP,0,0,0)&&gui[0]==1,"grey block reaches actual Forge GUI dispatcher; handler stops before screen/network");check(shell.onBlockActivated(w,P,shell.getDefaultState(),gp,EnumHand.MAIN_HAND,EnumFacing.UP,0,0,0)&&gui[0]==1,"non-grey consumes without GUI");
  java.lang.reflect.Field random=com.hbm.blocks.machine.MachineRTG.class.getDeclaredField("field_149933_a");random.setAccessible(true);((Random)random.get(rtg)).setSeed(4455);Random oracle=new Random(4455);float x=oracle.nextFloat()*.8F+.1F,y=oracle.nextFloat()*.8F+.1F,z=oracle.nextFloat()*.8F+.1F;w.setBlockToAir(P);int remaining=64,total=0;for(net.minecraft.entity.item.EntityItem d:w.drops){int count=Math.min(remaining,oracle.nextInt(21)+10);remaining-=count;total+=d.getItem().getCount();check(d.getItem().getItem()==pellet&&d.getItem().getCount()==count&&d.getItem().getItemDamage()==2,"seeded original drop partition item/count/damage including final emptied source");check(d.getItem().hasTagCompound()&&d.getItem().getTagCompound().getString("proof").equals("copied")&&d.getItem().getTagCompound()!=tag,"drop copies original item tag");check(d.posX==4+x&&d.posY==20+y&&d.posZ==4+z,"seeded drop position");check(d.motionX==(float)oracle.nextGaussian()*.05F&&d.motionY==(float)oracle.nextGaussian()*.05F+.2F&&d.motionZ==(float)oracle.nextGaussian()*.05F,"seeded original drop velocity");}check(total==64&&remaining==0&&w.getTileEntity(P)==null,"native break removes owner and conserves every inventory item");
 }
 static void decay(){
  VersatileConfig.decay=true;VersatileConfig.scale=true;ItemRTGPellet fuel=new ItemRTGPellet(40).setDecays(ItemRTGPelletDepleted.DepletedRTGMaterial.LEAD,4);fuel.setRegistryName("hbm","probe_decay");ForgeRegistries.ITEMS.register(fuel);ItemStack item=new ItemStack(fuel);ItemStack[] inv={item};int[] slots={0};check(RTGUtil.hasHeat(inv,slots),"real utility recognizes pellet");for(int expected:new int[]{40,30,20,10,0})check(RTGUtil.updateRTGs(inv,slots)==expected,"power uses remaining lifespan BEFORE decay");check(inv[0].getItem()==Items.IRON_INGOT&&inv[0].getMetadata()==3&&!RTGUtil.hasHeat(inv,slots),"exhausted pellet replacement preserves metadata");
  NativeWorld w=new NativeWorld(false);TileEntityMachineRTG a=w.put(P,rtg);for(int i=0;i<15;i++)a.setInventorySlotContents(i,new ItemStack(fuel));a.update();check(a.heatMax==600&&a.heat==600&&a.power==3000,"decay-enabled original 600 cap");check(a.getStackInSlot(0).getTagCompound().getLong("PELLET_DEPLETION")==3,"actual tile invokes actual decay");
  VersatileConfig.decay=false;VersatileConfig.scale=false;ItemStack fresh=new ItemStack(fuel);RTGUtil.updateRTGs(new ItemStack[]{fresh},slots);check(!fresh.hasTagCompound(),"disabled decay and scaling do not initialize lifespan");check(RTGUtil.getLifespan(1,com.hbm.interfaces.HalfLifeType.SHORT,false)==48000,"original short lifespan conversion");
 }
